-- A repository that turned private narrows the monitors that read it on its own provider: a GitLab project with a
-- GitHub repository's number is another repository.
CREATE FUNCTION public.narrow_repository_monitors(p_native_id bigint, p_provider_id bigint) RETURNS integer
    LANGUAGE plpgsql AS $$
DECLARE
    narrowed integer;
BEGIN
    UPDATE public.repository_to_monitor m
    SET proof_generation = m.proof_generation + 1,
        visibility_class = CASE WHEN m.visibility_class = 'WORKSPACE' THEN 'UNPROVEN' ELSE m.visibility_class END,
        proof_state = CASE WHEN m.visibility_class = 'WORKSPACE' THEN 'PENDING' ELSE m.proof_state END,
        proof_reason = CASE WHEN m.visibility_class = 'WORKSPACE' THEN 'AWAITING_READERS' ELSE m.proof_reason END,
        proof_changed_at = CASE WHEN m.visibility_class = 'WORKSPACE' THEN now() ELSE m.proof_changed_at END
    WHERE m.native_id = p_native_id
      AND (EXISTS (SELECT 1 FROM public.connection c
                 JOIN public.identity_provider p ON p.type = c.kind AND p.server_url = c.config ->> 'serverUrl'
                 WHERE c.kind IN ('GITHUB', 'GITLAB') AND c.state IN ('ACTIVE', 'SUSPENDED')
                   AND c.workspace_id = m.workspace_id AND p.id = p_provider_id)
         OR NOT EXISTS (SELECT 1 FROM public.connection c
                        WHERE c.kind IN ('GITHUB', 'GITLAB') AND c.state IN ('ACTIVE', 'SUSPENDED')
                          AND c.workspace_id = m.workspace_id));
    GET DIAGNOSTICS narrowed = ROW_COUNT;
    RETURN narrowed;
END
$$;
CREATE OR REPLACE FUNCTION public.narrow_monitors_of_repository() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM public.narrow_repository_monitors(
        CASE WHEN TG_OP = 'DELETE' THEN OLD.native_id ELSE NEW.native_id END,
        CASE WHEN TG_OP = 'DELETE' THEN OLD.provider_id ELSE NEW.provider_id END);
    RETURN NULL;
END
$$;
DROP FUNCTION public.narrow_repository_monitors(bigint);
-- A monitor belongs to the repository on its workspace's source provider. A workspace with no active source connection
-- cannot show which provider it read, so it is narrowed too.
CREATE FUNCTION public.forget_repository_readers(p_native_id bigint, p_provider_id bigint) RETURNS integer
    LANGUAGE plpgsql AS $$
DECLARE
    narrowed integer;
BEGIN
    -- Lock the monitors first: a listing that holds a monitor commits its readers before this deletes them.
    UPDATE public.repository_to_monitor m
    SET proof_generation = m.proof_generation + 1,
        visibility_class = 'UNPROVEN',
        proof_state = CASE WHEN m.proof_state = 'FAILED' THEN m.proof_state ELSE 'PENDING' END,
        proof_reason = CASE WHEN m.proof_state = 'FAILED' THEN m.proof_reason ELSE 'AWAITING_READERS' END,
        proof_changed_at = CASE WHEN m.visibility_class = 'UNPROVEN' THEN m.proof_changed_at ELSE now() END
    WHERE m.native_id = p_native_id
      AND (EXISTS (SELECT 1 FROM public.connection c
                 JOIN public.identity_provider p ON p.type = c.kind AND p.server_url = c.config ->> 'serverUrl'
                 WHERE c.kind IN ('GITHUB', 'GITLAB') AND c.state IN ('ACTIVE', 'SUSPENDED')
                   AND c.workspace_id = m.workspace_id AND p.id = p_provider_id)
         OR NOT EXISTS (SELECT 1 FROM public.connection c
                        WHERE c.kind IN ('GITHUB', 'GITLAB') AND c.state IN ('ACTIVE', 'SUSPENDED')
                          AND c.workspace_id = m.workspace_id));
    GET DIAGNOSTICS narrowed = ROW_COUNT;
    DELETE FROM public.resource_reader rr
    USING public.repository_to_monitor m
    WHERE rr.repository_to_monitor_id = m.id AND m.native_id = p_native_id AND rr.provider_id = p_provider_id;
    RETURN narrowed;
END
$$;
CREATE FUNCTION public.forget_repository_monitors_of_row() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM public.forget_repository_readers(OLD.native_id, OLD.provider_id);
    RETURN NULL;
END
$$;
DROP TRIGGER repository_gone ON public.repository;
CREATE TRIGGER repository_gone AFTER DELETE ON public.repository
    FOR EACH ROW EXECUTE FUNCTION public.forget_repository_monitors_of_row();
CREATE FUNCTION public.forget_readers_of_repositories(p_repository_ids bigint[], p_user_ids bigint[])
    RETURNS void LANGUAGE plpgsql AS $$
BEGIN
    IF cardinality(p_repository_ids) = 0 OR cardinality(p_user_ids) = 0 THEN
        RETURN;
    END IF;
    -- Lock and move on every monitor of the repositories first, so a listing that began before the removal does not
    -- apply, and one that holds a monitor commits before its rows are deleted.
    UPDATE public.repository_to_monitor m
    SET proof_generation = m.proof_generation + 1
    FROM public.repository r
    WHERE r.id = ANY (p_repository_ids) AND m.native_id = r.native_id
      AND (EXISTS (SELECT 1 FROM public.connection c
                 JOIN public.identity_provider p ON p.type = c.kind AND p.server_url = c.config ->> 'serverUrl'
                 WHERE c.kind IN ('GITHUB', 'GITLAB') AND c.state IN ('ACTIVE', 'SUSPENDED')
                   AND c.workspace_id = m.workspace_id AND p.id = r.provider_id)
         OR NOT EXISTS (SELECT 1 FROM public.connection c
                        WHERE c.kind IN ('GITHUB', 'GITLAB') AND c.state IN ('ACTIVE', 'SUSPENDED')
                          AND c.workspace_id = m.workspace_id));
    DELETE FROM public.resource_reader rr
    USING public.repository r, public.repository_to_monitor m, public."user" u
    WHERE r.id = ANY (p_repository_ids) AND m.native_id = r.native_id AND rr.repository_to_monitor_id = m.id
      AND rr.provider_id = r.provider_id
      AND u.id = ANY (p_user_ids) AND u.provider_id = rr.provider_id AND rr.reader_native_id = u.native_id;
END
$$;
CREATE FUNCTION public.forget_removed_collaborator() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM public.forget_readers_of_repositories(ARRAY[OLD.repository_id], ARRAY[OLD.user_id]);
    RETURN OLD;
END
$$;
CREATE TRIGGER repository_collaborator_removed BEFORE DELETE ON public.repository_collaborator
    FOR EACH ROW EXECUTE FUNCTION public.forget_removed_collaborator();
CREATE FUNCTION public.forget_removed_team_member() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM public.forget_readers_of_repositories(
        ARRAY(SELECT p.repository_id FROM public.team_repository_permission p WHERE p.team_id = OLD.team_id),
        ARRAY[OLD.user_id]);
    RETURN OLD;
END
$$;
CREATE TRIGGER team_membership_removed BEFORE DELETE ON public.team_membership
    FOR EACH ROW EXECUTE FUNCTION public.forget_removed_team_member();
CREATE FUNCTION public.forget_removed_team_access() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM public.forget_readers_of_repositories(
        ARRAY[OLD.repository_id],
        ARRAY(SELECT t.user_id FROM public.team_membership t WHERE t.team_id = OLD.team_id));
    RETURN OLD;
END
$$;
CREATE TRIGGER team_repository_permission_removed BEFORE DELETE ON public.team_repository_permission
    FOR EACH ROW EXECUTE FUNCTION public.forget_removed_team_access();
CREATE FUNCTION public.forget_removed_organization_member() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    PERFORM public.forget_readers_of_repositories(
        ARRAY(SELECT r.id FROM public.repository r WHERE r.organization_id = OLD.organization_id),
        ARRAY[OLD.user_id]);
    RETURN OLD;
END
$$;
CREATE TRIGGER organization_membership_removed BEFORE DELETE ON public.organization_membership
    FOR EACH ROW EXECUTE FUNCTION public.forget_removed_organization_member();

